#!/bin/sh
# Reproduces the TSV dumps the sprint scripts read. Read-only: sqlite3 -readonly on the live index; vault files are only read.
# Usage: dump-queries.sh <out-dir>   (then see the commands recorded in docs/spikes/intake-second-sprint/WP-1-FINDINGS.md)
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'docs/spikes/intake-second-sprint/dump-queries.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'dump-queries.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu
OUT=${1:?out dir}; IDX=${CV_INDEX_DB_LIVE:-$HOME/.cache/crucible-vault/index-3.db}; mkdir -p "$OUT"
# source, publication, day-folder flag, intake flag (post-id or message-id) for every note that has a source
sqlite3 -readonly -separator "$(printf '\t')" "$IDX" "select coalesce((select value from props where file_id=f.id and key='source'),''), coalesce((select value from props where file_id=f.id and key='publication'),''), (f.path like 'daily/day/%'), exists(select 1 from props where file_id=f.id and key in ('post-id','message-id')) from files f where f.is_md=1 and f.path not like '.trash/%' and exists(select 1 from props where file_id=f.id and key='source')" > "$OUT/src.tsv"
# path, publication, via, enriched for day-folder notes with a post-id
sqlite3 -readonly -separator "$(printf '\t')" "$IDX" "select f.path, coalesce((select value from props where file_id=f.id and key='publication'),''), coalesce((select value from props where file_id=f.id and key='via'),''), coalesce((select value from props where file_id=f.id and key='enriched'),'') from files f where f.path like 'daily/day/%' and f.is_md=1 and exists(select 1 from props where file_id=f.id and key='post-id')" > "$OUT/rss.tsv"
# path, via, enriched for every note (enriched-census.pl input; the sed unquotes the JSON via value)
sqlite3 -readonly -separator "$(printf '\t')" "$IDX" "select f.path, coalesce((select value from props where file_id=f.id and key='via'),''), coalesce((select value from props where file_id=f.id and key='enriched'),'') from files f where f.is_md=1 and f.path not like '.trash/%'" | sed 's/\t"\(.*\)"\t/\t\1\t/' > "$OUT/enr.tsv"
# clip path, duplicate-of value
sqlite3 -readonly -separator "$(printf '\t')" "$IDX" "select f.path, p.value from props p join files f on f.id=p.file_id where p.key='duplicate-of'" > "$OUT/dup.tsv"
